using UnityEngine;
using UnityEditor;
public class Diag {
  public static string Main() {
    var table = AssetDatabase.LoadAssetAtPath<FluMix.StringTable>("Assets/FluMix/Data/StringTable.asset");
    var q = AssetDatabase.LoadAssetAtPath<FluMix.QuestionBank>("Assets/FluMix/Data/QuestionBank.asset");
    var mixer = AssetDatabase.LoadAssetAtPath<UnityEngine.Audio.AudioMixer>("Assets/FluMix/Audio/FluMix.mixer");
    string groups = mixer == null ? "no mixer" : string.Join(",", System.Array.ConvertAll(mixer.FindMatchingGroups(""), g => g.name));
    return "table=" + (table == null ? "null" : table.entries.Count.ToString()) + " q=" + (q == null ? "null" : q.questions.Count.ToString()) + " mixer=" + groups;
  }
}
